ROOT = Path(__file__).resolve().parent
CSS = '''*{box-sizing:border-box} :root{color-scheme:light;--bg:#F7F2E8;--surface:#FFFCF5;--ink:#14352A;--muted:#3F5C50;--accent:#1F6B4E;--border:#E3DACB}body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.7 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--accent);text-underline-offset:4px}a:hover{text-decoration-thickness:2px}a:focus-visible{outline:3px solid var(--accent);outline-offset:5px}header{border-bottom:1px solid var(--border);padding:24px max(24px,calc((100vw - 1160px)/2));display:flex;justify-content:space-between;gap:24px;align-items:center}.brand{font-weight:700;letter-spacing:.04em;text-decoration:none;color:var(--ink)}.edition,.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}.layout{max-width:1200px;margin:auto;display:grid;grid-template-columns:240px minmax(0,1fr);gap:64px;padding:56px 24px 80px}nav{align-self:start;position:sticky;top:32px}nav a{display:block;min-height:44px;padding:10px 12px;text-decoration:none;border-radius:4px}nav a[aria-current=page]{background:var(--ink);color:var(--surface)}nav p{margin:0 12px 16px}main{max-width:68ch;min-width:0}h1,h2,h3{font-family:Georgia,"Times New Roman",serif;line-height:1.18;letter-spacing:-.025em}h1{font-size:clamp(38px,6vw,64px);font-weight:400;margin:12px 0 24px}h2{font-size:29px;margin:44px 0 16px}h3{font-size:23px}p{margin:0 0 18px}.lead{font-size:21px;line-height:1.55}.notice{padding:24px;background:var(--surface);border:1px solid var(--border);margin:28px 0}.directory{border-top:1px solid var(--border);margin-top:32px}.directory a{display:block;padding:24px 0;border-bottom:1px solid var(--border);font-size:23px;font-family:Georgia,serif}.directory small{display:block;color:var(--muted);font:16px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;margin-top:6px}li{padding-left:4px;margin-bottom:12px}footer{max-width:1152px;margin:auto;padding:24px;border-top:1px solid var(--border);display:flex;flex-wrap:wrap;justify-content:space-between;gap:16px;font-size:14px;color:var(--muted)}footer a{padding:10px 0;display:inline-block}.skip{position:absolute;left:16px;top:-100px;background:var(--surface);padding:12px;z-index:2}.skip:focus{top:12px}code{background:#EFE8DA;padding:2px 5px;overflow-wrap:anywhere}main a{overflow-wrap:anywhere}@media(max-width:800px){header{padding:20px 24px}.edition{max-width:120px;text-align:right}.layout{display:block;padding-top:24px}nav{position:static;display:flex;flex-wrap:wrap;gap:4px;border-bottom:1px solid var(--border);padding-bottom:24px;margin-bottom:36px}nav p{width:100%;margin-left:0}main{max-width:none}h2{margin-top:36px}}@media print{nav,.skip{display:none}.layout{display:block;padding:20px}body{font-size:12pt;background:white}header,footer{padding:12px}h1{font-size:30pt}}'''
HOME = '''<p class="eyebrow">Prismtrade LLC / Helios</p><h1>A clear view of your workspace.</h1><p class="lead">Helios is a read-only workspace client in development. This is its home for product information, privacy, and support.</p><div class="notice"><strong>Not publicly available yet.</strong><br>There is no App Store download at this time. These pages describe the current implementation, not a promise of future features.</div><h2>What Helios does today</h2><p>Pair with a compatible, self-hosted server to retrieve your authorized company workspace. Browse chat metadata, read history when supplied by the server, and view approval records.</p><p>The current app does not send messages, run agents, execute work, or offer an AI conversation feature. Approval records are not evidence that an action occurred.</p><h2>Your server, your workspace</h2><p>Your administrator supplies the server address and a single-use pairing credential. The app requires HTTPS with a valid certificate. The included local backend is a development foundation; secure ingress and real-device verification are still required before deployment.</p><p>Workspace data stays subject to your server operator’s access and retention practices. Disconnecting revokes a device session; it does not delete your organization’s records.</p><div class="directory"><a href="helios/privacy/index.html">Privacy policy <span aria-hidden="true">↗</span><small>Data handled by the app, the server, and this website.</small></a><a href="helios/support/index.html">Support &amp; connection help <span aria-hidden="true">↗</span><small>Pairing, troubleshooting, disconnection, and privacy requests.</small></a></div>'''
PRIVACY = '''<p class="eyebrow">Helios / Policy</p><h1>Privacy policy</h1><p class="lead">Understand what is handled, where it goes, and what you can control.</p><p>This policy describes the current Helios implementation by Prismtrade LLC and this informational website. Helios is in development and is not publicly available yet. Your independently operated workspace server may have its own privacy policy.</p><h2>Data the app handles</h2><ul><li><strong>Connection and session information:</strong> the server address, pairing credential, device token, session identifier, company identifier, and expiration time are used to establish and maintain authorized access.</li><li><strong>Workspace information:</strong> company and profile details, organization information, chat metadata, approval records, and any message history supplied by your server are received to display your workspace. Supplied history can include sender names, message text, and timestamps.</li></ul><p>The current connection flow keeps the retrieved workspace in memory. It stores the server address and session information in Apple Keychain using device-only, when-unlocked protection. Network requests use an ephemeral URL session. These controls are not a guarantee against access to a compromised device or server.</p><h2>Where information goes</h2><p>The app sends pairing and authenticated workspace requests to the HTTPS server you enter. The server operator controls that service and the records it supplies. Pairing is scoped to one company. Prismtrade LLC does not automatically receive your self-hosted workspace simply because you use the app.</p><p>The current app contains no analytics or advertising SDKs. It does not implement message sending, agent execution, or AI chat. No workspace content is sent to an AI provider by this current connection flow.</p><h2>The included local backend</h2><p>The development backend stores company profiles, chat metadata, session and pairing credential hashes, and any provisioned approval and audit records in local SQLite. SQLite storage is not encrypted by this implementation; the operator must protect the host and backups.</p><p>Pairing credentials are single-use and expire after five minutes. Device sessions expire after 24 hours and can be revoked. Only SHA-256 hashes of these credentials are stored by the backend. Credential expiration is not a deletion schedule for database records.</p><p>The optional Teams cache adapter imports chat topics and types, along with private source identifiers and provenance timestamps. It does not import member emails, member lists, message bodies, HTML, or previews, and is not a live synchronization service. The included backend does not currently ingest full message history; the client can nevertheless read history supplied by a compatible server.</p><h2>Retention and disconnection</h2><p>Workspace, audit, backup, and operational-log retention depends on the server administrator’s configuration and practices. There is no universal automatic deletion period promised here, and the development backend does not provide a complete retention-management system. Ask your operator what is retained and for how long.</p><p><strong>“Revoke session &amp; disconnect” is not account or workspace deletion.</strong> The app asks the server to revoke the token and verifies that the session can no longer read the workspace before removing its saved Keychain connection and in-memory snapshot. If revocation cannot be confirmed, it reports an error and retains the connection so you can retry. Uninstalling the app is not a reliable substitute for server-side revocation or deletion.</p><h2>This website and support email</h2><p>This static website embeds no cookies, analytics, tracking scripts, advertising, external fonts, third-party asset dependencies, or submission forms. It is hosted by GitHub Pages, which processes request information to operate and secure hosting. See <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub’s privacy statement</a>. A hosting service may process operational request information such as IP addresses, requested pages, timestamps, and browser information to deliver and secure the site. The actual host’s configuration and policy determine logging and retention; no exact hosting-log retention period is represented here.</p><p>If you email support, Prismtrade LLC receives your email address, message, and any attachments you choose to send, for responding to your request. Email services process that correspondence. Do not include tokens, pairing credentials, passwords, or confidential workspace exports. Support correspondence retention depends on handling needs and applicable obligations; this policy does not promise a fixed deletion period or a particular vendor guarantee.</p><h2>Your choices and privacy rights</h2><p>Depending on your location and applicable law, you may have rights to access, correct, delete, restrict, or object to processing of personal information, or request a portable copy. Contact your workspace administrator for server-held records. Contact <a href="mailto:info@iqonhealth.com">info@iqonhealth.com</a> for Prismtrade LLC privacy questions, support-correspondence deletion, or help directing a request. We may need to verify your identity and authority without asking for your session token.</p><p>Deleting a device session does not delete organizational records, audit history, backups, or records held by other services. Your administrator should explain any technical or legal limits on deletion. You may also have the right to contact your local data protection authority.</p><h2>Changes and contact</h2><p>We will revise this page as actual product behavior changes. Future capabilities are not covered as if already implemented. For questions, email <a href="mailto:info@iqonhealth.com">info@iqonhealth.com</a> or visit <a href="../support/index.html">support</a>.</p>'''
SUPPORT = '''<p class="eyebrow">Helios / Help</p><h1>Support</h1><p class="lead">Connection help and privacy requests, without sharing your secrets.</p><div class="notice"><strong>Contact Prismtrade LLC</strong><br><a href="mailto:info@iqonhealth.com">info@iqonhealth.com</a><br>For Helios questions and privacy requests. No response-time guarantee is offered.</div><h2>Before you connect</h2><p>Helios is not publicly available yet. The current app is read-only and requires a compatible, self-hosted server. Your administrator is responsible for providing and securing that server. The included loopback-only backend is not ready for direct iPhone use without reviewed HTTPS ingress and end-to-end verification.</p><ol><li>Obtain your administrator’s HTTPS server origin with a valid certificate. Enter only the origin, such as <code>https://your-server.example</code>, without credentials, a path, query, or fragment.</li><li>Ask the operator for a fresh single-use pairing credential. In the included backend it expires after five minutes. Do not email or post it.</li><li>Enter the address and credential, then choose <strong>Pair securely</strong>. The session is limited to the company selected by the operator.</li><li>Use <strong>Refresh workspace</strong> to retrieve current server data. No successful offline fallback is provided.</li></ol><h2>Troubleshooting</h2><h3>Expired or invalid session</h3><p>Pairing credentials can be used once. Included-backend device sessions expire after 24 hours. An expired, invalid, or revoked credential needs a new pairing credential from your operator.</p><h3>Cannot reach the server</h3><p>Check connectivity, the exact HTTPS origin, and certificate validity with your administrator. Do not disable transport security or expose the local development server directly to the internet. If pairing is rate-limited, wait at least 60 seconds before retrying.</p><h3>Empty chats or history</h3><p>The app displays only what your authorized server supplies. The current metadata adapter imports chat topics and types, not full messages. Empty history is not evidence of lost messages or a live synchronization failure. Ask your administrator about available records.</p><h3>Messages or actions cannot be sent</h3><p>This is expected. The app does not send messages, make approval decisions, run agents, or execute work. Displayed approval statuses are records only.</p><h2>Revoke a session</h2><p>Select <strong>Revoke session &amp; disconnect</strong>. The app verifies server rejection of the revoked session before clearing its saved connection. If it reports “Revocation not confirmed,” restore connectivity and retry, or ask the server operator to revoke access. Do not assume a failed disconnect, app removal, or token expiration deletes workspace data.</p><h2>Request access, correction, or deletion</h2><p>Contact the workspace administrator for server-held information and backup or audit retention. Email <a href="mailto:info@iqonhealth.com">info@iqonhealth.com</a> for help identifying the appropriate contact, questions about your rights, or deletion of support correspondence held by Prismtrade LLC. Explain the category of data and the request; avoid sending the data itself. Read the <a href="../privacy/index.html">privacy policy</a> for the distinction between revocation and deletion.</p><h2>What to include in a support request</h2><ul><li>Your app version and iOS version, if available.</li><li>The steps you took and the exact error text.</li><li>Whether pairing, refresh, or disconnection failed.</li><li>A redacted screenshot only if needed.</li></ul><p><strong>Never send passwords, pairing codes, device tokens, authorization headers, or confidential message history.</strong> Redact private server details and personal information. For a lost device or suspected unauthorized access, contact the server administrator promptly to revoke its session.</p>'''
def page(title, body, active, prefix):
    links = [('home', prefix+'index.html', 'Overview'), ('privacy', prefix+'helios/privacy/index.html', 'Privacy policy'), ('support', prefix+'helios/support/index.html', 'Support')]
    nav = ''.join(f'<a href="{url}"'+(' aria-current="page"' if key == active else '')+f'>{label}</a>' for key,url,label in links)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{title} — Helios by Prismtrade LLC. Current product information, privacy and support."><title>{title} | Helios · Prismtrade LLC</title><link rel="stylesheet" href="{prefix}assets/site.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="{prefix}index.html">PRISMTRADE LLC</a><span class="edition">Helios / Documentation</span></header><div class="layout"><nav aria-label="Documentation"><p class="eyebrow">Learn about Helios</p>{nav}</nav><main id="main">{body}</main></div><footer><span>Helios by Prismtrade LLC · In development</span><a href="mailto:info@iqonhealth.com">info@iqonhealth.com</a></footer></body></html>'''
for name, content in [('assets/site.css',CSS),('index.html',page('Overview',HOME,'home','')),('helios/privacy/index.html',page('Privacy policy',PRIVACY,'privacy','../../')),('helios/support/index.html',page('Support',SUPPORT,'support','../../'))]:
    path=ROOT/name
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(content)
print('Built three complete static pages and local stylesheet.')
